import{_ as s,o as t,c as i,a5 as e}from"./chunks/framework.CcrBcQWS.js";const u=JSON.parse('{"title":"RBQ Simulator","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/simulator/overview.md","filePath":"software/simulator/overview.md","lastUpdated":1787021357000}'),n={name:"software/simulator/overview.md"};function o(l,a,r,p,h,c){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="rbq-simulator" tabindex="-1">RBQ Simulator <a class="header-anchor" href="#rbq-simulator" aria-label="Permalink to &quot;RBQ Simulator&quot;">​</a></h1><p>The RBQ open-source package ships several simulators that fall into two groups with <strong>different purposes</strong>:</p><ul><li><strong>Open-source physics simulators</strong> — <a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo</a> and <a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo</a> run the <strong>full RBQ software stack</strong> (Motion / Vision / GUI) against a simulation, so you can develop and test robot software without hardware.</li><li><strong>Reinforcement-learning training environments</strong> — <a href="/RBQ/nightly/software/simulator/rbq-gym.html">Isaac Gym</a> and <a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab</a> let you <strong>train a locomotion policy</strong> and <strong>deploy it</strong> to the real robot.</li></ul><h2 id="simulators" tabindex="-1">Simulators <a class="header-anchor" href="#simulators" aria-label="Permalink to &quot;Simulators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Simulator</th><th>Engine</th><th>Package path</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>MuJoCo</strong></td><td>MuJoCo</td><td><code>rbq_simulator/rbq_mujoco/</code></td><td>Run the full RBQ stack in simulation</td></tr><tr><td><strong>Gazebo</strong></td><td>Ignition Gazebo (Fortress)</td><td><code>rbq_simulator/rbq_gazebo/</code></td><td>Run the full RBQ stack in simulation, with a ROS 2 sensor bridge</td></tr><tr><td><strong>Isaac Gym</strong></td><td>IsaacGym (Preview 4)</td><td><code>rbq_simulator/rbq_gym/</code></td><td>RL training — fast parallel training</td></tr><tr><td><strong>Isaac Lab</strong></td><td>Isaac Sim / Isaac Lab</td><td><code>rbq_simulator/rbq_lab/</code></td><td>RL training — high-fidelity simulation</td></tr></tbody></table><h2 id="running-the-full-rbq-stack-mujoco-gazebo" tabindex="-1">Running the full RBQ stack (MuJoCo / Gazebo) <a class="header-anchor" href="#running-the-full-rbq-stack-mujoco-gazebo" aria-label="Permalink to &quot;Running the full RBQ stack (MuJoCo / Gazebo)&quot;">​</a></h2><p>MuJoCo and Gazebo join the running RBQ stack as DDS peers on domain 0 / loopback. Start the stack, then the simulator:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the RBQ stack (Motion / Vision / GUI)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sim</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Then start a simulator, e.g. MuJoCo</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_mujoco</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_mujoco</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resources/model/default.xml</span></span></code></pre></div><p>See <a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo</a> and <a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo</a> for the full build and run instructions.</p><h2 id="training-deploying-a-policy-isaac-gym-isaac-lab" tabindex="-1">Training &amp; deploying a policy (Isaac Gym / Isaac Lab) <a class="header-anchor" href="#training-deploying-a-policy-isaac-gym-isaac-lab" aria-label="Permalink to &quot;Training &amp; deploying a policy (Isaac Gym / Isaac Lab)&quot;">​</a></h2><p>The RL environments follow the same <strong>Train → Play → Deploy</strong> pipeline:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Train (Isaac Gym or Isaac Lab)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Play  (verify policy in same simulator)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Sim2Sim (MuJoCo, via rbq_low_level)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Deploy (real robot)</span></span></code></pre></div><p>After training, the <code>policy.onnx</code> and <code>info.json</code> artifacts are loaded by <code>rbq_low_level</code> for on-robot execution.</p><h2 id="repository-structure" tabindex="-1">Repository structure <a class="header-anchor" href="#repository-structure" aria-label="Permalink to &quot;Repository structure&quot;">​</a></h2><p>All simulator code lives under <code>rbq_simulator/</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RBQ/</span></span>
<span class="line"><span>└── rbq_simulator/</span></span>
<span class="line"><span>    ├── rbq_mujoco/        # MuJoCo simulator (full-stack)</span></span>
<span class="line"><span>    ├── rbq_gazebo/        # Ignition Gazebo simulator (full-stack + ROS 2 bridge)</span></span>
<span class="line"><span>    ├── rbq_gym/           # Isaac Gym RL environment</span></span>
<span class="line"><span>    └── rbq_lab/           # Isaac Lab RL environment</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/simulator/mujoco.html">MuJoCo →</a> — run the full stack in MuJoCo</li><li><a href="/RBQ/nightly/software/simulator/gazebo.html">Gazebo →</a> — run the full stack in Gazebo</li><li><a href="/RBQ/nightly/software/simulator/rbq-gym.html">Isaac Gym →</a> — Isaac Gym training guide</li><li><a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab →</a> — Isaac Lab training guide</li><li><a href="/RBQ/nightly/software/sdk/cpp/low-level.html">Low Level (RL Policy) →</a> — deploy a trained policy to the real robot</li></ul>`,18)])])}const m=s(n,[["render",o]]);export{u as __pageData,m as default};
